gboolean /* <=== gimp_image_set_resolution */ 
gimp_image_set_resolution (gint32  image_ID,
                           gdouble xresolution,
                           gdouble yresolution)
{
  GimpParam *return_vals;
  gint nreturn_vals;
  gboolean success = TRUE;

  return_vals = gimp_run_procedure ("gimp-image-set-resolution",
                                    &nreturn_vals,
                                    GIMP_PDB_IMAGE, image_ID,
                                    GIMP_PDB_FLOAT, xresolution,
                                    GIMP_PDB_FLOAT, yresolution,
                                    GIMP_PDB_END);

  success = return_vals[0].data.d_status == GIMP_PDB_SUCCESS;

  gimp_destroy_params (return_vals, nreturn_vals);

  return success;
}

gboolean   gimp_image_set_colormap        (gint32          image_ID, /* <=== gimp_image_set_colormap */ 
                                           const guchar   *colormap,
